<?php get_header(); $q=kzfr_filter_value('q'); $genre=kzfr_filter_value('genre'); $args=[]; if($q !== '') { $search_args=['post_type'=>'kzfr_program','post_status'=>'publish','posts_per_page'=>-1,'fields'=>'ids']; $text_ids=get_posts(array_merge($search_args,['s'=>$q])); $host_ids=get_posts(array_merge($search_args,['meta_query'=>[['key'=>'kzfr_host','value'=>$q,'compare'=>'LIKE']]])); $args['post__in']=array_values(array_unique(array_merge($text_ids,$host_ids))) ?: [0]; } if($genre) $args['tax_query']=[['taxonomy'=>'kzfr_genre','field'=>'slug','terms'=>$genre]]; $programs=kzfr_query('kzfr_program',-1,$args); ?>
<div class="section-wrap section-space"><?php kzfr_page_intro('PROGRAM DIRECTORY','Programs','Browse KZFR programs by title, host, or category.'); ?>
<form class="filter-bar" method="get" role="search"><input type="hidden" name="design" value="<?php echo esc_attr(kzfr_current_design()); ?>"><div class="field field-grow"><label for="program-search">Search programs</label><input id="program-search" type="search" name="q" value="<?php echo esc_attr($q); ?>" placeholder="Program title or host name"></div><div class="field"><label for="genre-filter">Category</label><select name="genre" id="genre-filter"><option value="">Every category</option><?php foreach(get_terms(['taxonomy'=>'kzfr_genre','hide_empty'=>true]) as $term): ?><option value="<?php echo esc_attr($term->slug); ?>" <?php selected($genre,$term->slug); ?>><?php echo esc_html($term->name); ?></option><?php endforeach; ?></select></div><button class="button button-dark" type="submit">Find programs </button><a class="text-link" href="<?php echo kzfr_url('programs'); ?>">Reset</a></form>
<p class="result-count" role="status"><?php echo esc_html($programs->found_posts.' '.((int)$programs->found_posts===1 ? 'program' : 'programs')); ?></p><div class="program-grid"><?php $i=0; while($programs->have_posts()):$programs->the_post(); kzfr_program_card(get_the_ID(),$i++); endwhile; wp_reset_postdata(); ?></div><?php if(!$programs->found_posts): ?><div class="empty-state"><h2>No programs found.</h2><p>Try another word or choose every category.</p></div><?php endif; ?><aside class="source-note">Program information comes from <a href="https://www.kzfr.org/programs">KZFR’s public listings</a>. Check the official schedule for changes.</aside></div>
<?php get_footer(); ?>
